:root {
  --card-bg: #ffffff;
  --header-bg: #2d5a27;
  --header-text: #ffffff;
  --subtitle-text: #a8d5a2;
  --badge-bg: #f0fce8;
  --badge-text: #2d5a27;
  --season-text: #c5e8bf;
  --zone-bg: #f7fdf4;
  --zone-border: #d4edcf;
  --zone-a-accent: #e8f5e0;
  --zone-b-accent: #e0f5e8;
  --zone-c-accent: #e8fae0;
  --zone-d-accent: #fdf5e0;
  --status-growing-bg: #d4edcf;
  --status-growing-text: #2d6e26;
  --status-ready-bg: #c8f0d4;
  --status-ready-text: #1a6b3a;
  --status-planted-bg: #fde8c8;
  --status-planted-text: #8a5a1a;
  --stat-bg: #f7fdf4;
  --stat-value: #2d5a27;
  --stat-label: #7aaa74;
  --divider: #d4edcf;
  --footer-bg: #f2fbee;
  --avatar-bg: #2d5a27;
  --avatar-text: #ffffff;
  --owner-name: #2a3828;
  --owner-since: #8aab84;
  --btn-bg: #3a7a32;
  --btn-text: #ffffff;
  --zone-name: #3a5436;
  --card-border: #c8e0c4;
}

.plot-card {
  background: var(--card-bg);
  border: 1.5px solid var(--card-border);
  border-radius: 16px;
  width: 460px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.plot-header {
  background: var(--header-bg);
  padding: 14px 18px 12px;
}

.plot-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 6px;
}

.plot-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 20px;
  letter-spacing: 0.04em;
}

.plot-season {
  color: var(--season-text);
  font-size: 12px;
  font-weight: 500;
}

.plot-title {
  color: var(--header-text);
  font-size: 20px;
  font-weight: 700;
  margin: 0 0 2px;
  line-height: 1.2;
}

.plot-subtitle {
  color: var(--subtitle-text);
  font-size: 12px;
  font-weight: 400;
  margin: 0;
}

.plot-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  padding: 12px 14px;
  background: var(--card-bg);
}

.plot-zone {
  background: var(--zone-bg);
  border: 1.5px solid var(--zone-border);
  border-radius: 10px;
  padding: 10px 6px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  margin: 0;
}

.zone-a { background: var(--zone-a-accent); }
.zone-b { background: var(--zone-b-accent); }
.zone-c { background: var(--zone-c-accent); }
.zone-d { background: var(--zone-d-accent); }

.zone-icon {
  font-size: 22px;
  line-height: 1;
}

.zone-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--zone-name);
  text-align: center;
}

.zone-status {
  font-size: 10px;
  font-weight: 600;
  padding: 2px 7px;
  border-radius: 10px;
  letter-spacing: 0.02em;
}

.zone-status.growing {
  background: var(--status-growing-bg);
  color: var(--status-growing-text);
}

.zone-status.ready {
  background: var(--status-ready-bg);
  color: var(--status-ready-text);
}

.zone-status.planted {
  background: var(--status-planted-bg);
  color: var(--status-planted-text);
}

.plot-stats {
  display: flex;
  align-items: center;
  justify-content: space-around;
  background: var(--stat-bg);
  border-top: 1px solid var(--divider);
  border-bottom: 1px solid var(--divider);
  padding: 10px 18px;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--stat-value);
  line-height: 1;
}

.stat-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--stat-label);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.stat-divider {
  width: 1px;
  height: 30px;
  background: var(--divider);
}

.plot-footer {
  background: var(--footer-bg);
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.owner-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.owner-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--avatar-bg);
  color: var(--avatar-text);
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.owner-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.owner-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--owner-name);
}

.owner-since {
  font-size: 11px;
  color: var(--owner-since);
}

.log-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 16px;
  cursor: pointer;
}
